"""图像模板资源管理中心。

集中管理所有业务操作和战斗系统所需的图像模板，
替代原先分散在 ``combat/image_resources.py`` 和 ``ops/image_resources.py`` 中的实现。

核心组件
--------
- :class:`TemplateKey` — 枚举值标识每一组模板，替代硬编码字符串
- :class:`CombatTemplates` — 战斗系统专用模板
- :class:`Templates` — 业务操作模板（食堂、建造、确认弹窗等）
- :func:`get_templates` — 通过 ``TemplateKey`` 获取模板列表

Usage::

    from autowsgr.image_resources import TemplateKey, CombatTemplates, Templates

    # 枚举键查询模板列表
    templates = TemplateKey.FORMATION.templates

    # 直接属性访问
    tpl = CombatTemplates.FORMATION
    btn = Templates.Cook.COOK_BUTTON
"""

from __future__ import annotations

import hashlib
import json
import threading
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from autowsgr.image_resources._lazy import LazyTemplate
from autowsgr.image_resources.combat import CombatTemplates
from autowsgr.image_resources.keys import TemplateKey, get_templates
from autowsgr.image_resources.ops import Templates


__all__ = [
    'CombatTemplates',
    'LazyTemplate',
    'TemplateKey',
    'Templates',
    'get_manifest_report',
    'get_templates',
    'validate_manifest',
]


# ═══════════════════════════════════════════════════════════════════════════════
# 模板清单校验（R39）
# ═══════════════════════════════════════════════════════════════════════════════
#
# manifest.json 由 generate_manifest.py 生成。校验是只读的：只比对文件存在性、
# 尺寸与 SHA-256，不修改模板、不参与识别路径，失败也不会阻断导入。

_MANIFEST_PATH = Path(__file__).resolve().parent / 'manifest.json'
_IMAGE_ROOT = Path(__file__).resolve().parent.parent / 'data' / 'images'
_PNG_SIGNATURE = b'\x89PNG\r\n\x1a\n'
_MANIFEST_LOCK = threading.Lock()
_manifest_report: dict[str, Any] | None = None


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def _png_size(path: Path) -> tuple[int, int]:
    with path.open('rb') as handle:
        header = handle.read(24)
    if len(header) < 24 or header[:8] != _PNG_SIGNATURE:
        raise ValueError('不是有效的 PNG 文件')
    return (
        int.from_bytes(header[16:20], 'big'),
        int.from_bytes(header[20:24], 'big'),
    )


def _manifest_logger():
    from autowsgr.infra.logger import get_logger

    return get_logger('image_resources')


def _log_manifest_report(report: dict[str, Any]) -> None:
    try:
        log = _manifest_logger()
    except Exception:  # pragma: no cover - 日志初始化失败不能影响导入
        return
    errors = report['errors']
    if errors:
        log.error('模板清单校验失败（{} 项不一致）', len(errors))
        for error in errors:
            log.error('{}', error)
    else:
        log.info('模板清单校验通过（{} 项）', report['checked'])


def validate_manifest(*, force: bool = False) -> dict[str, Any]:
    """校验 ``manifest.json`` 与实际模板文件是否一致。

    只读校验：对清单内每个模板比对存在性、PNG 尺寸与 SHA-256，并检查目录中
    是否存在清单未收录的 PNG。结果缓存在模块级，``force=True`` 时重新校验。

    Returns
    -------
    dict
        ``ok`` / ``errors`` / ``checked`` / ``manifest_path`` / ``game_version``
        / ``generated_at`` / ``validated_at``。
    """
    global _manifest_report  # noqa: PLW0603
    with _MANIFEST_LOCK:
        if _manifest_report is not None and not force:
            return _manifest_report

        errors: list[str] = []
        checked = 0
        game_version = ''
        generated_at = ''

        if not _MANIFEST_PATH.is_file():
            errors.append(f'清单文件缺失：{_MANIFEST_PATH.name}')
        else:
            try:
                manifest = json.loads(_MANIFEST_PATH.read_text(encoding='utf-8'))
            except (OSError, json.JSONDecodeError) as exc:
                errors.append(f'清单无法读取：{exc}')
            else:
                game_version = str(manifest.get('game_version') or '')
                generated_at = str(manifest.get('generated_at') or '')
                templates = manifest.get('templates')
                if not isinstance(templates, list):
                    errors.append('清单格式错误：templates 必须是数组')
                else:
                    expected: dict[str, dict[str, Any]] = {}
                    for entry in templates:
                        if isinstance(entry, dict) and isinstance(entry.get('path'), str):
                            expected[entry['path']] = entry
                    actual: dict[str, Path] = {}
                    if _IMAGE_ROOT.is_dir():
                        actual = {
                            path.relative_to(_IMAGE_ROOT).as_posix(): path
                            for path in _IMAGE_ROOT.rglob('*')
                            if path.is_file() and path.suffix.lower() == '.png'
                        }

                    for relative_path in sorted(expected):
                        entry = expected[relative_path]
                        path = _IMAGE_ROOT / relative_path
                        if not path.is_file():
                            errors.append(f'清单缺失：{relative_path}')
                            continue
                        checked += 1
                        try:
                            actual_width, actual_height = _png_size(path)
                            actual_sha = _sha256(path)
                        except (OSError, ValueError) as exc:
                            errors.append(f'无法读取：{relative_path}（{exc}）')
                            continue

                        expected_width = entry.get('width')
                        expected_height = entry.get('height')
                        if (expected_width, expected_height) != (
                            actual_width,
                            actual_height,
                        ):
                            errors.append(
                                f'尺寸不一致：{relative_path}'
                                f'（期望 {expected_width}x{expected_height}，'
                                f'实际 {actual_width}x{actual_height}）'
                            )
                        expected_sha = entry.get('sha256')
                        if expected_sha != actual_sha:
                            errors.append(
                                f'哈希不一致：{relative_path}'
                                f'（期望 {expected_sha}，实际 {actual_sha}）'
                            )

                    for relative_path in sorted(set(actual) - set(expected)):
                        errors.append(f'清单未收录：{relative_path}')

        report: dict[str, Any] = {
            'ok': not errors,
            'errors': errors,
            'checked': checked,
            'manifest_path': str(_MANIFEST_PATH),
            'game_version': game_version,
            'generated_at': generated_at,
            'validated_at': datetime.now(timezone.utc).isoformat(timespec='seconds'),
        }
        _manifest_report = report
        _log_manifest_report(report)
        return report


def get_manifest_report() -> dict[str, Any]:
    """返回启动校验结果；尚未校验时先执行一次。"""
    return validate_manifest()


try:
    validate_manifest()
except Exception as _exc:  # pragma: no cover - 校验绝不能阻断模块导入
    _manifest_report = {
        'ok': False,
        'errors': [f'模板清单校验异常：{_exc}'],
        'checked': 0,
        'manifest_path': str(_MANIFEST_PATH),
        'game_version': '',
        'generated_at': '',
        'validated_at': datetime.now(timezone.utc).isoformat(timespec='seconds'),
    }
    try:
        _manifest_logger().error('{}', _manifest_report['errors'][0])
    except Exception:
        pass
